    /// <summary>Replaces the old privacy text with the new one, but only where the admin has not edited it.</summary>
    public static async Task<bool> UpgradePrivacyAsync(AppDbContext db, CancellationToken ct = default)
    {
        var page = await db.Pages.Include(p => p.Translations).FirstOrDefaultAsync(p => p.SystemKey == SystemPages.Privacy, ct);
        if (page is null) return false;
        var changed = false;
        foreach (var t in page.Translations)
            if (Legacy.TryGetValue(t.LanguageCode, out var old) && t.Content == old && Privacy.TryGetValue(t.LanguageCode, out var text))
            {
                t.Content = text;
                changed = true;
            }
        if (changed) await db.SaveChangesAsync(ct);
        return changed;
    }
}
